  checkparent() {
    var count = 0
    for (var i = 0; i < this.familyarray.length; ++i) {
      if (this.familyarray[i].relDesc == 'Mother' || this.familyarray[i].relDesc == 'Father') {
        count++
      }
    }
    if (count > 1) {
      return true
    }
    return false
  }
