  getstatus(param) {
    var status = "";  // Default to an empty string


  // Handle "transferee" status
  if (this.global.studinfo.enrollmentType == 2 && this.global.enrollmenthist[0].schoolYear == this.global.schoolyear && param == "transferee") {
    status = '√';
  }
  // Handle "old" status
  else if (this.global.studinfo.enrollmentType == 1 && this.global.enrollmenthist.length > 1 && param == "old"){
    status = '√';
  }
  // Handle "new" status
  else if (  this.global.enrollmenthist[0].schoolYear == this.global.schoolyear  && this.global.studinfo.enrollmentType == 1 &&  param == "new") {
    status = '√';
  }

  return status;  // Return the status text (√ or "")
}
